2588	/// Called by the apprt when the surface's display is unrealized (the surface
2589	/// is being destroyed or reparented). Safe to call from the main thread.
2590	pub fn displayUnrealized(self: *Surface) void {
2591	    self.renderer.displayUnrealized();
