201	test isSafe {
202	    const testing = std.testing;
203	    try testing.expect(isSafe("hello"));
204	    try testing.expect(isSafe("hello\tworld"));
205	    try testing.expect(!isSafe("hello\n"));
206	    try testing.expect(!isSafe("hello\nworld"));
207	    try testing.expect(!isSafe("he\x1b[201~llo"));
208	
209	    // A carriage return is the Enter key on the input stream, so it
210	    // can execute a command exactly like a newline.
211	    try testing.expect(!isSafe("hello\r"));
212	    try testing.expect(!isSafe("hello\rworld"));
213	    try testing.expect(!isSafe("hello\r\nworld"));
214	    try testing.expect(!isSafe("\r"));
215	}
