220	    // Bracketed: line terminators are fine, the frame terminator is not.
221	    try testing.expect(isSafeWith("hello", .{ .bracketed = true }));
222	    try testing.expect(isSafeWith("hello\nworld", .{ .bracketed = true }));
223	    try testing.expect(isSafeWith("hello\rworld", .{ .bracketed = true }));
224	    try testing.expect(isSafeWith("hello\r\nworld", .{ .bracketed = true }));
225	    try testing.expect(!isSafeWith("he\x1b[201~llo", .{ .bracketed = true }));
226	    try testing.expect(!isSafeWith("hello\n\x1b[201~", .{ .bracketed = true }));
227	
228	    // Unbracketed: the conservative rule.
229	    try testing.expect(isSafeWith("hello", .{ .bracketed = false }));
230	    try testing.expect(!isSafeWith("hello\nworld", .{ .bracketed = false }));
231	    try testing.expect(!isSafeWith("hello\rworld", .{ .bracketed = false }));
232	    try testing.expect(!isSafeWith("hello\r", .{ .bracketed = false }));
233	    try testing.expect(!isSafeWith("he\x1b[201~llo", .{ .bracketed = false }));
