438	fn setupFd(src: File.Handle, target: i32) !void {
439	    const PosixCall = struct {
440	        fn f(func: anytype, args: anytype) !usize {
441	            while (true) {
442	                const rc = @call(.auto, func, args);
443	                switch (posix.errno(rc)) {
444	                    .SUCCESS => return @intCast(rc),
445	                    .INTR => continue,
446	                    .AGAIN, .ACCES => return error.Locked,
447	                    .BADF => unreachable,
448	                    .BUSY => return error.FileBusy,
449	                    .INVAL => unreachable, // invalid parameters
450	                    .PERM => return error.PermissionDenied,
451	                    .MFILE => return error.ProcessFdQuotaExceeded,
452	                    .NOTDIR => unreachable, // invalid parameter
453	                    .DEADLK => return error.DeadLock,
454	                    .NOLCK => return error.LockedRegionLimitExceeded,
455	                    else => |err| return posix.unexpectedErrno(err),
456	                }
457	            }
458	        }
459	    };
460	
461	    switch (builtin.target.os.tag) {
462	        .linux => {
463	            // We use dup3 so that we can clear CLO_ON_EXEC. We do NOT want this
464	            // file descriptor to be closed on exec since we're exactly exec-ing after
465	            // this.
466	            _ = try PosixCall.f(linux.dup3, .{ src, target, 0 });
467	        },
468	        .freebsd, .ios, .macos => {
469	            // Mac doesn't support dup3 so we use dup2. We purposely clear
470	            // CLO_ON_EXEC for this fd.
471	            const flags = try PosixCall.f(posix.system.fcntl, .{ src, posix.F.GETFD });
472	            if (flags & posix.FD_CLOEXEC != 0) {
473	                _ = try PosixCall.f(
474	                    posix.system.fcntl,
475	                    .{ src, posix.F.SETFD, flags & ~@as(u32, posix.FD_CLOEXEC) },
476	                );
477	            }
478	
479	            _ = try PosixCall.f(posix.system.dup2, .{ src, target });
480	        },
481	        else => @compileError("unsupported platform"),
482	    }
483	}
