 546	/// Record a release event for the active left-click gesture.
 547	///
 548	/// This stops autoscroll and updates `left_click_dragged`, but it does not clear
 549	/// the click count or time. Keeping that state is what lets the next nearby press
 550	/// become a double- or triple-click. Call `reset` instead if the release should
 551	/// cancel the click sequence entirely.
 552	///
 553	/// Pass the release pin when the pointer position maps to a valid terminal cell.
 554	/// If it does not, pass null; the gesture then conservatively records that the
 555	/// pointer moved away from the original pressed cell. This is useful for callers
 556	/// that use `left_click_dragged` after release to decide whether a click should
 557	/// activate links or other hit targets.
 558	pub fn release(
 559	    self: *SelectionGesture,
 560	    t: *Terminal,
 561	    r: Release,
 562	) void {
 563	    if (self.left_click_count == 0) {
 564	        assert(self.left_drag_autoscroll == .none);
 565	        return;
 566	    }
 567	
 568	    if (r.pin) |release_pin| {
 569	        if (self.validatedLeftClickPin(&t.screens)) |click_pin| {
 570	            if (!release_pin.eql(click_pin.*)) self.left_click_dragged = true;
 571	        } else {
 572	            // If the original anchor is no longer valid, conservatively treat
 573	            // this as a drag/cancelled click so callers don't perform click-only
 574	            // actions on a different or recycled screen.
 575	            self.left_click_dragged = true;
 576	        }
 577	    } else {
 578	        self.left_click_dragged = true;
 579	    }
 580	    self.left_drag_autoscroll = .none;
